MAP
    NAME "SS_MAP_GRAL_CUENTAS"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE 'includes/temp_directory.map'
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END
    END
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_numero_cuentas.log"
    DEBUG 0
    CONFIG "LABELCACHE" "ON"
    LAYER
        NAME "SS_MAP_GRAL_CUENTAS_AT"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        DATA 'geometry from predios using unique gid using srid=32614'
        LABELCACHE ON
        STATUS DEFAULT
        MAXSCALE 4000
        TYPE POLYGON
        LABELITEM "cuenta"
        CLASS
            NAME "numero de cuenta"
            LABEL
                WRAP ","
                ANGLE AUTO
                POSITION AUTO
                PARTIALS FALSE
                MINFEATURESIZE AUTO
                PRIORITY 5
                SIZE 13
                COLOR 0 0 0
                TYPE TRUETYPE
                FONT 'arial'
                OFFSET 0 22
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP